import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { SkillBlockCard } from "./SkillBlockCard";
import type { BlockRuntimeStatus } from "./types";

describe("SkillBlockCard", () => {
  it("falls back to the inactive style for an unknown status", () => {
    renderWithProviders(
      <SkillBlockCard
        blockId="main"
        status={"skipped" as BlockRuntimeStatus}
        expanded={false}
        onToggle={vi.fn()}
      />,
    );

    const card = screen.getByTestId("skill-block-card");
    expect(card).toBeInTheDocument();
    // Unknown status is treated as inactive: no active/completed label shown.
    expect(card).toHaveAttribute("data-status", "skipped");
    expect(screen.queryByText("active")).not.toBeInTheDocument();
  });

  it("shows only the block id in the header, no description", () => {
    renderWithProviders(
      <SkillBlockCard blockId="main" status="inactive" expanded={false} onToggle={vi.fn()} />,
    );

    expect(screen.getByText("ordered_block · main")).toBeInTheDocument();
  });
});
